INSERT INTO level_rule (rule_version, level, min_exp, title_key, frame_code)
SELECT #{target}, level, min_exp, title_key, frame_code
FROM level_rule WHERE rule_version = #{source}

INSERT INTO gamification_abuse_policy (policy_version, review_score_threshold)
SELECT #{target}, review_score_threshold
FROM gamification_abuse_policy WHERE policy_version = #{source}

INSERT INTO gamification_public_policy (policy_version, title, content_text, status)
SELECT #{target}, title, content_text, 'DRAFT'
FROM gamification_public_policy WHERE policy_version = #{source}

mapper.select:
SELECT policy_version AS policyVersion, review_score_threshold AS reviewScoreThreshold
FROM gamification_abuse_policy WHERE policy_version = #{policyVersion}
LIMIT 1

mapper.delete:
DELETE FROM quest_reward
WHERE policy_version = #{policyVersion} AND quest_code = #{questCode}
  AND campaign_code = 'DEFAULT'

mapper.update:
UPDATE gamification_policy_bundle
SET content_hash = #{contentHash}, change_reason = #{reason}, version = version + 1
WHERE id = #{id} AND status = 'DRAFT' AND version = #{expectedVersion}

UPDATE gamification_policy_bundle
SET status = 'APPROVED', approved_by = #{operatorId}, approved_at = #{at},
    change_reason = #{reason}, version = version + 1
WHERE id = #{id} AND status = 'PENDING_APPROVAL' AND version = #{expectedVersion}
  AND created_by <> #{operatorId}

