INSERT INTO gamification_public_policy_audit
    (policy_id, event_type, from_status, to_status, operator_id)
SELECT id, #{eventType}, #{fromStatus}, #{toStatus}, #{operatorId}
FROM gamification_public_policy WHERE policy_version = #{policyVersion}
